import { bibleBookChapterCounts } from '../data/bibleBookChapters';
import { Choice, GameVerse, Question, QuizMode, verseKey } from './types';

type Random = () => number;
const normalized = (value: string) =>
  value.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g, ' ').trim();
export function shuffle<T>(items: readonly T[], random: Random = Math.random): T[] {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}
export const referenceLabel = (verse: GameVerse, bookName: (book: string) => string) =>
  `${bookName(verse.book)} ${verse.chapter}:${verse.verse}`;

function tokens(text: string, locale: string): Array<{ word: string; index: number }> {
  const segments =
    typeof Intl.Segmenter === 'function'
      ? [...new Intl.Segmenter(locale, { granularity: 'word' }).segment(text)]
          .filter((part) => part.isWordLike)
          .map((part) => ({ word: part.segment, index: part.index }))
      : [...text.matchAll(/[\p{L}\p{M}]+(?:['’][\p{L}\p{M}]+)*/gu)].map((match) => ({
          word: match[0],
          index: match.index ?? 0,
        }));
  return segments.filter(
    ({ word }) =>
      [...word].length >= (/\p{Script=Han}/u.test(word) ? 1 : 3) && [...word].length <= 16,
  );
}

/** The first verse is the target; distractors must be different text/references. */
export function buildQuestion(
  pool: GameVerse[],
  mode: QuizMode,
  random: Random = Math.random,
  bookName: (book: string) => string = (book) => book,
  locale = 'en',
): Question | null {
  const target = pool[0];
  if (!target) {
    return null;
  }
  let prompt = target.text;
  let hint = mode === 'easy' ? bookName(target.book) : '';
  let choices: Choice[];
  let answerId: string;
  const different = pool.filter(
    (verse) =>
      verse.translation === target.translation &&
      verseKey(verse) !== verseKey(target) &&
      normalized(verse.text) !== normalized(target.text),
  );
  if (mode === 'blank') {
    const candidates = shuffle(tokens(target.text, locale), random);
    const words = different.flatMap((verse) => tokens(verse.text, locale).map(({ word }) => word));
    const missing = candidates.find(
      ({ word }) =>
        new Set(words.filter((other) => normalized(other) !== normalized(word)).map(normalized))
          .size >= 2,
    );
    if (!missing) {
      return null;
    }
    const otherWords = [
      ...new Map(
        words
          .filter((word) => normalized(word) !== normalized(missing.word))
          .map((word) => [normalized(word), word]),
      ).values(),
    ];
    answerId = `word:${normalized(missing.word)}`;
    choices = [
      { id: answerId, label: missing.word },
      ...shuffle(otherWords, random)
        .slice(0, 2)
        .map((word) => ({ id: `word:${normalized(word)}`, label: word })),
    ];
    prompt =
      target.text.slice(0, missing.index) +
      '_____' +
      target.text.slice(missing.index + missing.word.length);
    hint = referenceLabel(target, bookName);
  } else {
    const available =
      mode === 'easy' ? different.filter((verse) => verse.book === target.book) : different;
    const distractors = shuffle(
      [
        ...new Map(
          available.map((verse) => [
            mode === 'hard' ? normalized(verse.text) : verseKey(verse),
            verse,
          ]),
        ).values(),
      ],
      random,
    ).slice(0, 2);
    if (distractors.length !== 2) {
      return null;
    }
    answerId = verseKey(target);
    if (mode === 'hard') {
      prompt = referenceLabel(target, bookName);
    }
    choices = [target, ...distractors].map((verse) => ({
      id: verseKey(verse),
      label:
        mode === 'hard'
          ? verse.text
          : mode === 'easy'
            ? `${verse.chapter}:${verse.verse}`
            : referenceLabel(verse, bookName),
    }));
  }
  return {
    verse: target,
    mode,
    prompt,
    hint,
    choices: shuffle(choices, random) as [Choice, Choice, Choice],
    answerId,
  };
}

export function buildDeck(
  pool: GameVerse[],
  mode: QuizMode,
  bookName: (book: string) => string,
  locale: string,
  random: Random = Math.random,
): Question[] {
  const unique = [...new Map(pool.map((verse) => [verseKey(verse), verse])).values()];
  const questions = shuffle(unique, random).flatMap((target) => {
    const question = buildQuestion(
      [target, ...unique.filter((v) => verseKey(v) !== verseKey(target))],
      mode,
      random,
      bookName,
      locale,
    );
    return question ? [question] : [];
  });
  return questions.slice(0, 10);
}

export interface QuizRound {
  version: 1;
  translation: string;
  mode: QuizMode;
  questions: Question[];
  answers: Array<string | null>;
  index: number;
  startedAt?: number;
  finishedAt?: number;
}
export function newRound(
  questions: Question[],
  translation: string,
  mode: QuizMode,
  now = Date.now(),
): QuizRound {
  return {
    version: 1,
    translation,
    mode,
    questions,
    answers: questions.map(() => null),
    index: 0,
    startedAt: now,
  };
}
export function answerQuestion(round: QuizRound, choice: string, now = Date.now()): QuizRound {
  const question = round.questions[round.index];
  if (
    !question ||
    round.answers[round.index] !== null ||
    !question.choices.some((item) => item.id === choice)
  ) {
    return round;
  }
  return {
    ...round,
    ...(round.startedAt !== undefined && round.index === round.questions.length - 1
      ? { finishedAt: Math.max(round.startedAt, now) }
      : {}),
    answers: round.answers.map((answer, index) => (index === round.index ? choice : answer)),
  };
}
export function nextQuestion(round: QuizRound): QuizRound {
  return round.index < round.questions.length && round.answers[round.index] !== null
    ? { ...round, index: round.index + 1 }
    : round;
}
export const quizScore = (round: QuizRound) =>
  round.questions.filter((q, index) => round.answers[index] === q.answerId).length;
export const missedQuestions = (round: QuizRound) =>
  round.questions.filter((q, index) => round.answers[index] !== q.answerId);

/** Local practice snapshots are bounded and validated; scores are always derived. */
export function restoreQuiz(
  raw: string | null,
  translation: string,
  mode: QuizMode,
): QuizRound | null {
  if (!raw || raw.length > 100000) {
    return null;
  }
  try {
    const round = JSON.parse(raw);
    if (
      round.version !== 1 ||
      round.translation !== translation ||
      round.mode !== mode ||
      !Array.isArray(round.questions) ||
      !round.questions.length ||
      round.questions.length > 10 ||
      !Array.isArray(round.answers) ||
      round.answers.length !== round.questions.length ||
      !Number.isInteger(round.index) ||
      round.index < 0 ||
      round.index > round.questions.length
    ) {
      return null;
    }
    for (const [index, q] of round.questions.entries()) {
      const v = q?.verse;
      if (
        !v ||
        v.translation !== translation ||
        !Object.prototype.hasOwnProperty.call(bibleBookChapterCounts, v.book) ||
        !Number.isInteger(v.chapter) ||
        v.chapter < 1 ||
        v.chapter > bibleBookChapterCounts[v.book] ||
        !Number.isInteger(v.verse) ||
        v.verse < 1 ||
        typeof v.text !== 'string' ||
        v.text.length > 900 ||
        q.mode !== mode ||
        typeof q.prompt !== 'string' ||
        q.prompt.length > 1000 ||
        typeof q.hint !== 'string' ||
        q.hint.length > 200 ||
        !Array.isArray(q.choices) ||
        q.choices.length !== 3 ||
        !q.choices.every(
          (c: Choice) =>
            c &&
            typeof c.id === 'string' &&
            c.id.length < 100 &&
            typeof c.label === 'string' &&
            c.label.length > 0 &&
            c.label.length <= 900,
        ) ||
        new Set(q.choices.map((c: Choice) => c.id)).size !== 3 ||
        new Set(q.choices.map((c: Choice) => normalized(c.label))).size !== 3 ||
        !q.choices.some((c: Choice) => c.id === q.answerId) ||
        (round.answers[index] !== null &&
          !q.choices.some((c: Choice) => c.id === round.answers[index])) ||
        (index < round.index && round.answers[index] === null) ||
        (index > round.index && round.answers[index] !== null)
      ) {
        return null;
      }
    }
    const { startedAt, finishedAt, ...progress } = round;
    const complete = round.answers.every((answer: string | null) => answer !== null);
    const validStart = Number.isSafeInteger(startedAt) && startedAt >= 0 && startedAt <= Date.now();
    const validFinish =
      Number.isSafeInteger(finishedAt) && finishedAt >= startedAt && finishedAt <= Date.now();
    // Preserve valid answers even when legacy or malformed timestamps cannot be used.
    if (validStart && (complete ? validFinish : finishedAt === undefined)) {
      return { ...progress, startedAt, ...(complete ? { finishedAt } : {}) } as QuizRound;
    }
    return progress as QuizRound;
  } catch {
    return null;
  }
}
