import { readGameStorage, writeGameStorage } from './storage';
import { restoreWordle, utcDay, WordList, wordleOutcome, WordleState } from './wordleEngine';

export const LEADERBOARD_INTENT_KEY = 'revelationary.wordle.leaderboard-intent.v1';
export const WORDLE_SIGNUP_URL = '/study/#/login?mode=signup&redirect=wordle-leaderboard';
export interface LeaderboardIntent {
  version: 1;
  game: 'wordle';
  day: string;
  publicName: string;
  owner: string | null;
}
export const validPublicName = (name: string): boolean =>
  /^[\p{L}\p{N} ._-]{2,24}$/u.test(name.trim());
export function parseLeaderboardIntent(raw: string | null): LeaderboardIntent | null {
  try {
    const intent = raw && raw.length < 1000 ? JSON.parse(raw) : null;
    if (
      intent?.version !== 1 ||
      intent.game !== 'wordle' ||
      typeof intent.day !== 'string' ||
      !/^\d{4}-\d{2}-\d{2}$/.test(intent.day) ||
      typeof intent.publicName !== 'string' ||
      !validPublicName(intent.publicName) ||
      !(
        intent.owner === null ||
        (typeof intent.owner === 'string' && intent.owner.length > 0 && intent.owner.length <= 128)
      )
    ) {
      return null;
    }
    return {
      version: 1,
      game: 'wordle',
      day: intent.day,
      publicName: intent.publicName.trim(),
      owner: intent.owner,
    };
  } catch {
    return null;
  }
}
/** Persist both the result and consent before navigating away; never lose a score silently. */
export function prepareLeaderboardSignup(
  game: WordleState,
  publicName: string,
  words: WordList,
): boolean {
  if (
    game.day !== utcDay() ||
    wordleOutcome(game, words.words) !== 'won' ||
    !validPublicName(publicName)
  ) {
    return false;
  }
  const key = `revelationary.wordle.v1.guest.${game.day}`;
  if (!writeGameStorage(key, game)) {
    return false;
  }
  const stored = restoreWordle(readGameStorage(key), game.day, words.words, words.allowedGuesses);
  if (stored.guesses.join(',') !== game.guesses.join(',')) {
    return false;
  }
  const intent: LeaderboardIntent = {
    version: 1,
    game: 'wordle',
    day: game.day,
    publicName: publicName.trim(),
    owner: null,
  };
  return writeGameStorage(LEADERBOARD_INTENT_KEY, intent);
}
export function readLeaderboardIntent(): LeaderboardIntent | null {
  return parseLeaderboardIntent(readGameStorage(LEADERBOARD_INTENT_KEY));
}
/** Binding is persisted before any request, so another account cannot inherit consent. */
export function bindLeaderboardIntent(
  intent: LeaderboardIntent,
  owner: string,
): LeaderboardIntent | null {
  if (intent.day !== utcDay() || (intent.owner !== null && intent.owner !== owner)) {
    return null;
  }
  const bound = { ...intent, owner };
  if (!writeGameStorage(LEADERBOARD_INTENT_KEY, bound)) {
    return null;
  }
  const stored = readLeaderboardIntent();
  return stored?.owner === owner &&
    stored.day === bound.day &&
    stored.publicName === bound.publicName
    ? stored
    : null;
}
export function clearLeaderboardIntent(owner: string, day: string) {
  const intent = readLeaderboardIntent();
  if (intent?.owner === owner && intent.day === day) {
    try {
      localStorage.removeItem(LEADERBOARD_INTENT_KEY);
    } catch {
      /* Idempotent server retries remain safe. */
    }
  }
}
